DECLARE
  new_org_id UUID;
  caller_role TEXT;
BEGIN
  -- Verify caller is administrator
  SELECT role INTO caller_role FROM public.mp_profiles WHERE id = auth.uid();
  IF caller_role != 'administrator' THEN
    RAISE EXCEPTION 'Access denied: Only administrators can setup organisations.';
  END IF;

  -- 1. Create Organisation
  INSERT INTO public.mp_organisations (name)
  VALUES (org_name)
  RETURNING id INTO new_org_id;

  -- 2. Create Supervisor
  PERFORM public.mp_admin_create_user(
    supervisor_email,
    supervisor_password,
    supervisor_name,
    'supervisor',
    new_org_id
  );

  RETURN new_org_id;
END;

DECLARE
  new_org_id UUID;
  new_admin_id UUID;
BEGIN
  -- 1. Verify caller is administrator
  IF NOT (SELECT public.is_system_owner()) THEN
    RAISE EXCEPTION 'Only administrators can perform this action';
  END IF;

  -- 2. Create the Organisation
  INSERT INTO public.mp_organisations (name, logo_url)
  VALUES (org_name, org_logo_url)
  RETURNING id INTO new_org_id;

  -- 3. Assign Org Admin
  IF admin_mode = 'existing' THEN
    IF admin_user_id IS NULL THEN
      RAISE EXCEPTION 'admin_user_id is required for existing user mode';
    END IF;

    -- Verify user exists
    IF NOT EXISTS (SELECT 1 FROM public.mp_profiles WHERE id = admin_user_id) THEN
      RAISE EXCEPTION 'User not found';
    END IF;

    -- Add membership to the new organisation with 'org-admin' role
    INSERT INTO public.mp_memberships (user_id, organisation_id, role, status)
    VALUES (admin_user_id, new_org_id, 'org-admin', 'active')
    ON CONFLICT (user_id, organisation_id) DO UPDATE SET role = 'org-admin', status = 'active';

  ELSE -- 'new' user mode
    IF admin_email IS NULL OR admin_password IS NULL OR admin_name IS NULL THEN
      RAISE EXCEPTION 'Admin email, name and password are required for new user mode';
    END IF;

    -- Call existing creation helper to handle auth.users and profile
    new_admin_id := public.mp_admin_create_user(
      admin_email,
      admin_password,
      admin_name,
      'org-admin',
      new_org_id
    );

    -- Create membership record (create_user helper doesn't do this)
    INSERT INTO public.mp_memberships (user_id, organisation_id, role, status)
    VALUES (new_admin_id, new_org_id, 'org-admin', 'active');
  END IF;

  RETURN new_org_id;
END;

DECLARE
  v_pair RECORD;
  v_author_name TEXT;
BEGIN
  SELECT mentor_id, mentee_id INTO v_pair
  FROM mp_pairs
  WHERE id = NEW.pair_id;

  SELECT full_name INTO v_author_name
  FROM mp_profiles
  WHERE id = NEW.author_id;

  IF NOT NEW.is_private THEN
    IF NEW.author_id = v_pair.mentor_id THEN
      PERFORM mp_create_notification(
        v_pair.mentee_id,
        'note_added',
        'New Note Added',
        v_author_name || ' added a note',
        '/mentee/notes',
        NEW.id
      );
    ELSE
      PERFORM mp_create_notification(
        v_pair.mentor_id,
        'note_added',
        'New Note Added',
        v_author_name || ' added a note',
        '/mentor/notes',
        NEW.id
      );
    END IF;
  END IF;

  RETURN NEW;
END;

